                runner._completedChecks.Add(request.ScenarioId == "B015-FIXED-PREFIX-TARGETS"
                    ? "B015FixedPrefixTargets:LegalGeneratedTarget:AbsentTargetRejected:NativeUnchanged"
                    : "AdjustedRouteInvalidSuffix");
            }
