                runner._completedChecks.Add("BaseLibCardModifierBoundary");
                runner._completedChecks.Add("BaseLibGeneratedClone:NativeState:Created:Hand:Draw:Discard:Exhaust:Play:Removed");
            }

            if (request.ExportBugReportAfterSetup)
            {
                runner.SetStage("export_bug_report");
                string directory = ProjectSettings.GlobalizePath("user://combat-solver-test-bug-reports");
                string archivePath = await CombatBugReportExporter.ExportCurrentAsync(directory);
                using ZipArchive archive = ZipFile.OpenRead(archivePath);
                AssertBugReportArchive(archive, "current", request.ExpectedBugReportControlMode);
                runner._completedChecks.Add($"BugReport:{Path.GetFileName(archivePath)}");
            }
        }

        public void AssertAfterExecution(ScenarioContext scenario, ExecutionOutcome outcome)
        {
            // Keep actual terminal health alongside projected search metrics, so full-battle
            // comparisons cannot accidentally report a solver estimate as native outcome.
            runner._completedChecks.Add($"NativeOutcome:combatEnded={outcome.CombatEnded}:turn={outcome.FinishedTurn}"
                + $":hp={scenario.Player.Creature.CurrentHp}:maxHp={scenario.Player.Creature.MaxHp}");
            UnattendedTestRequest request = runner._request;
            if (request.ExpectedFinishedTurn is { } expectedFinishedTurn
                && outcome.FinishedTurn != expectedFinishedTurn)
            {
                throw new InvalidOperationException(
                    $"战斗在第 {outcome.FinishedTurn} 回合结束，预期为第 {expectedFinishedTurn} 回合。");
            }
            if (request.ExpectedFinishedTurnAtMost is { } maximumFinishedTurn
                && outcome.FinishedTurn > maximumFinishedTurn)
            {
                throw new InvalidOperationException(
                    $"战斗在第 {outcome.FinishedTurn} 回合结束，超过预期上限第 {maximumFinishedTurn} 回合。");
            }
            if (request.ExpectedFinishedPlayerHpAtLeast is { } minimumFinishedHp
                && scenario.Player.Creature.CurrentHp < minimumFinishedHp)
            {
                throw new InvalidOperationException(
                    $"战斗结束时玩家剩余 {scenario.Player.Creature.CurrentHp} HP，低于预期下限 {minimumFinishedHp}。");
            }
            if (request.ExpectedPlayedCardId is { } expectedPlayedCardId && !outcome.ExpectedCardPlayed)
                throw new InvalidOperationException($"战斗中没有打出预期卡牌 {expectedPlayedCardId}。");
            if (request.ExpectedUsedPotionId is { } expectedUsedPotionId && !outcome.ExpectedPotionUsed)
                throw new InvalidOperationException($"战斗中没有使用预期药水 {expectedUsedPotionId}。");
            if (request.ExpectedObservedPlayerPowerId is { } expectedPowerId
                && !outcome.ExpectedPlayerPowerObserved)
            {
                throw new InvalidOperationException($"战斗中没有观察到玩家获得 {expectedPowerId}。");
            }
            AssertNativeChoices(request);
        }

        private void AssertNativeChoices(UnattendedTestRequest request)
        {
            if (request.ExpectedNativeChoiceVisibleAtLeast is null
                && request.ExpectedNativeChoiceSearchStartedAtMost is null)
                return;
            IEnumerable<NativeChoiceTrace> traces = NativeChoiceRuntime.TraceSnapshotForTesting;
            if (!string.IsNullOrWhiteSpace(request.ExpectedNativeChoiceOwnerPrefix))
            {
                traces = traces.Where(trace => trace.Owner.StartsWith(
                    request.ExpectedNativeChoiceOwnerPrefix,
                    StringComparison.Ordinal));
            }
            if (request.ExpectedNativeChoiceSurface is { } surface)
                traces = traces.Where(trace => trace.Surface == surface);
            NativeChoiceTrace[] matching = traces.ToArray();
            int visible = matching.Count(trace => trace.Stage == "Visible");
            int selected = matching.Count(trace => trace.Stage == "Selected");
            int searchStarted = matching.Count(trace => trace.Stage == "SearchStarted");
            if (request.ExpectedNativeChoiceVisibleAtLeast is { } expectedVisible
                && (visible < expectedVisible || selected < expectedVisible))
            {
                throw new InvalidOperationException(
                    $"原生选牌页面可见/完成次数为 {visible}/{selected}，低于预期 {expectedVisible}。 ");
            }
            if (request.ExpectedNativeChoiceSearchStartedAtMost is { } maximumSearches
                && searchStarted > maximumSearches)
            {
                throw new InvalidOperationException(
                    $"原生选牌页面期间启动了 {searchStarted} 次搜索，超过上限 {maximumSearches}。 ");
            }
            runner._completedChecks.Add(
                $"NativeChoices:{request.ExpectedNativeChoiceOwnerPrefix ?? "*"}:" +
                $"{request.ExpectedNativeChoiceSurface?.ToString() ?? "*"}:" +
                $"visible={visible}:selected={selected}:search={searchStarted}");
        }
    }
}

using System.Collections.Frozen;
using System.Reflection;
using HarmonyLib;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver.Engine.Common;

// A captured root's permission to replace the audited native comparison chain.
// Shared entries retain only immutable ModelId/type metadata, never gameplay models.
internal sealed class NativeCardSortProfile(bool enabled)
{
    private static readonly Guid AuditedModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly MethodInfo[] AuditedMethods =
    [
        typeof(CardModel).GetMethod(nameof(CardModel.CompareTo), [typeof(AbstractModel)])!,
        typeof(AbstractModel).GetMethod(nameof(AbstractModel.CompareTo), [typeof(AbstractModel)])!,
        typeof(ModelId).GetMethod(nameof(ModelId.CompareTo), [typeof(ModelId)])!,
        typeof(AbstractModel).GetProperty(nameof(AbstractModel.Id))!.GetMethod!,
        typeof(CardModel).GetProperty(nameof(CardModel.CurrentUpgradeLevel))!.GetMethod!,
        typeof(ModelId).GetProperty(nameof(ModelId.Category))!.GetMethod!,
        typeof(ModelId).GetProperty(nameof(ModelId.Entry))!.GetMethod!,
    ];
    internal sealed record Entry(ModelId Id, int Rank);
    private static readonly Lazy<FrozenDictionary<Type, Entry>> Entries = new(BuildEntries);

    internal bool Enabled => enabled;
    internal int RegisteredTypeCount => enabled ? Entries.Value.Count : 0;

    internal static NativeCardSortProfile Capture()
        => CaptureForModule(typeof(CardModel).Module.ModuleVersionId);

    // The caller is root capture. Patch eligibility is immutable for its workers/Forks.
    internal static NativeCardSortProfile CaptureForModule(Guid module)
        => new(module == AuditedModule && AuditedMethods.All(method =>
            method.Module.ModuleVersionId == AuditedModule
            && Harmony.GetPatchInfo(method) is not { Owners.Count: > 0 }));

    internal bool TryGetKey(PredictedCard card, out int rank, out int upgrade)
    {
        if (enabled && card.TryPrepareNativeSortIdentity(this, out rank))
        {
            upgrade = card.Preview.CurrentUpgradeLevel;
            return true;
        }
        rank = upgrade = 0;
        return false;
    }

    internal bool TryResolveIdentity(CardModel card, out Entry? entry)
    {
        if (enabled && Entries.Value.TryGetValue(card.GetType(), out Entry? found)
            && ReferenceEquals(card.Id, found.Id))
        {
            entry = found;
            return true;
        }
        entry = null;
        return false;
    }

    private static FrozenDictionary<Type, Entry> BuildEntries()
    {
        // Both native comparers use ordinal ModelId ordering. Equal IDs must get
        // the same rank so the original List.Sort tie behavior remains unchanged.
        return ModelDb.All.OfType<CardModel>()
            .Where(card => card.GetType().Assembly == typeof(CardModel).Assembly
                && card.GetType().GetMethod(nameof(CardModel.CompareTo), [typeof(AbstractModel)])
                    ?.DeclaringType == typeof(CardModel))
            .GroupBy(card => (card.Id.Category, card.Id.Entry))
            .OrderBy(group => group.Key.Category, StringComparer.Ordinal)
            .ThenBy(group => group.Key.Entry, StringComparer.Ordinal)
            .SelectMany((group, rank) => group.Select(card =>
                new KeyValuePair<Type, Entry>(card.GetType(), new(card.Id, rank))))
            .ToFrozenDictionary();
    }
}

