using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Extensions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private void AssertNativeCardSortProjection(CombatState live, Player player)
    {
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        NativeCardSortProfile profile = root.CardSortProfile;
        if (!profile.Enabled || profile.RegisteredTypeCount == 0)
            throw new InvalidOperationException("The native sort profile was not exercised.");
        List<PredictedCard> all = ModelDb.All.OfType<CardModel>()
            .Where(card => card.GetType().Assembly == typeof(CardModel).Assembly)
            .Select(card => new PredictedCard(card)).ToList();
        int pairs = 0, rejected = 0;
        foreach (PredictedCard left in all)
        {
            if (!profile.TryGetKey(left, out int leftRank, out int leftUpgrade)) { rejected++; continue; }
            foreach (PredictedCard right in all)
            {
                if (!profile.TryGetKey(right, out int rightRank, out int rightUpgrade)) continue;
                int native = Math.Sign(left.CompareTo(right));
                int candidate = Math.Sign(left.CompareNativeSortIdentity(right));
                if (candidate != native) throw new InvalidOperationException("Native ordinal rank differs.");
                pairs++;
            }
        }
        all.RemoveAll(card => !profile.TryGetKey(card, out _, out _));
        CombatPredictionSimulator parent = root.ForkSimulator();
        PredictedCard first = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        PredictedCard second = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        first.MutablePreview.BaseReplayCount = 1;
        second.MutablePreview.BaseReplayCount = 2;
        parent.AddToPile(first, PileType.Hand); parent.AddToPile(second, PileType.Hand);
        if (!profile.TryGetKey(first, out _, out _) || !profile.TryGetKey(second, out _, out _))
            throw new InvalidOperationException("Parent immutable metadata was not prepared before Fork.");
        CombatPredictionSimulator child = parent.Fork();
        PredictedCard childFirst = child.State.GetPlayerCombatState(player).Hand.Cards
            .Single(card => ReferenceEquals(card.Original, first.Original));
        childFirst.MutablePreview.UpgradeInternal();
        if (!profile.TryGetKey(childFirst, out int upgradedRank, out int upgraded)
            || !profile.TryGetKey(first, out int parentRank, out int parentUpgrade)
            || upgradedRank != parentRank || upgraded != 1 || parentUpgrade != 0)
            throw new InvalidOperationException("Current upgrade or parent isolation was lost.");
        string State(CombatPredictionSimulator simulator) => ContinuationStamp.CapturePredicted(
            player, simulator, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
        string parentBefore = State(parent), childBefore = State(child);
        int cases = 0;
        void Check(List<PredictedCard> source, NativeCardSortProfile current,
            CombatPredictionSimulator simulator, bool expectedFastPath)
        {
            List<PredictedCard> baseline = [.. source], candidate = [.. source];
            var a = simulator.Rng.ShuffleState.ToRng(); var b = simulator.Rng.ShuffleState.ToRng();
            baseline.StableShuffle(a);
            bool fast = ProjectedShuffleSort.TrySort(candidate, current);
            if (fast != expectedFastPath) throw new InvalidOperationException("Sort gate was not exercised.");
            if (fast) candidate.UnstableShuffle(b); else CombatBeamSolver.StableShuffleProjection(candidate, b);
            if (!baseline.SequenceEqual(candidate, ReferenceEqualityComparer.Instance)
                || a.CaptureState() != b.CaptureState())
                throw new InvalidOperationException("Projected native ordering or full RNG differs.");
            Interlocked.Increment(ref cases);
        }
        Check(all, profile, parent, true);
        Check([second, first, first, second], profile, parent, true);
        Check([first, second, first, second], profile, parent, true);
        Check([childFirst, first, second], profile, child, true);
        PredictedCard materialized = new(ModelDb.Card<StrikeIronclad>());
        if (!profile.TryGetKey(materialized, out _, out _))
            throw new InvalidOperationException("Unmaterialized root metadata was not prepared.");
        materialized.MaterializePreview();
        materialized.MutablePreview.UpgradeInternal();
        PredictedCard cloned = first.Clone();
        cloned.MutablePreview.UpgradeInternal();
        Check([first, materialized, cloned, second], profile, parent, true);
        if (first.Preview.CurrentUpgradeLevel != 0 || cloned.Preview.CurrentUpgradeLevel != 1)
            throw new InvalidOperationException("Clone metadata captured a mutable upgrade.");
        CardModel altered = PredictionUtils.CloneCardStateForSimulation(first.Preview);
        PredictedCard changedId = new(altered, altered);
        if (!profile.TryGetKey(changedId, out _, out _))
            throw new InvalidOperationException("Changed-ID probe did not start from admitted metadata.");
        FieldInfo idField = typeof(AbstractModel).GetFields(
            BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly)
            .Single(field => field.FieldType == typeof(ModelId));
        ModelId originalId = altered.Id;
        try
        {
            idField.SetValue(altered, new ModelId(originalId.Category, originalId.Entry + "_SORT_PROBE"));
            List<PredictedCard> changedInput = [second, changedId, first], changedBefore = [.. changedInput];
            if (ProjectedShuffleSort.TrySort(changedInput, profile)
                || !changedInput.SequenceEqual(changedBefore, ReferenceEqualityComparer.Instance))
                throw new InvalidOperationException("Cached metadata admitted a changed instance ID.");
            Check([second, changedId, first], profile, parent, false);
        }
        finally { idField.SetValue(altered, originalId); }
        Check([second, changedId, first], profile, parent, true);
        Random order = new(20261005);
        foreach (int size in new[] { 0, 1, 2, 3, 8, 16, 17, 32, 63, 128, 396, 4097 })
        {
            List<PredictedCard> source = Enumerable.Range(0, size)
                .Select(_ => all[order.Next(all.Count)]).ToList();
            Check(source, profile, parent, true);
        }
        var unknown = new PredictedCard(CreateUnknownSortCard());
        List<PredictedCard> unknownInput = [first, second, unknown], untouched = [.. unknownInput];
        if (ProjectedShuffleSort.TrySort(unknownInput, profile)
            || !unknownInput.SequenceEqual(untouched, ReferenceEqualityComparer.Instance))
            throw new InvalidOperationException("Unknown source was sorted or partially reordered.");
        Check([first, second], NativeCardSortProfile.CaptureForModule(Guid.Empty), parent, false);
        CombatPredictionSimulator[] siblings = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        Parallel.For(0, siblings.Length, index =>
        {
            using IDisposable workerIsolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator sibling = siblings[index];
            PredictedCard siblingFirst = sibling.State.GetPlayerCombatState(player).Hand.Cards
                .Single(card => ReferenceEquals(card.Original, first.Original));
            if ((index & 1) == 0) siblingFirst.MutablePreview.UpgradeInternal();
            string before = State(sibling);
            Check(sibling.State.GetPlayerCombatState(player).Hand.Cards.ToList(), profile, sibling, true);
            if (before != State(sibling))
                throw new InvalidOperationException("Parallel projection changed a sibling state or RNG.");
        });

        Harmony harmony = new("CombatSolver.Tests.NativeCardSort");
        MethodInfo countPrefix = typeof(UnattendedTestRunner).GetMethod(nameof(SortNoOpPrefix),
            BindingFlags.Static | BindingFlags.NonPublic)!;
        foreach (MethodInfo target in new[]
            { typeof(CardModel).GetMethod(nameof(CardModel.CompareTo), [typeof(AbstractModel)])!,
              typeof(AbstractModel).GetMethod(nameof(AbstractModel.CompareTo), [typeof(AbstractModel)])!,
              typeof(ModelId).GetMethod(nameof(ModelId.CompareTo), [typeof(ModelId)])!,
              typeof(AbstractModel).GetProperty(nameof(AbstractModel.Id))!.GetMethod!,
              typeof(CardModel).GetProperty(nameof(CardModel.CurrentUpgradeLevel))!.GetMethod!,
              typeof(ModelId).GetProperty(nameof(ModelId.Category))!.GetMethod!,
              typeof(ModelId).GetProperty(nameof(ModelId.Entry))!.GetMethod! })
        {
            try
            {
                harmony.Patch(target, prefix: new HarmonyMethod(countPrefix));
                NativeCardSortProfile patched = CombatRootSnapshot.Capture(live).CardSortProfile;
                if (patched.Enabled) throw new InvalidOperationException("A patched native method was certified.");
                Check([second, first, second, first], patched, parent, false);
            }
            finally { harmony.Unpatch(target, countPrefix); }
        }
        if (!CombatRootSnapshot.Capture(live).CardSortProfile.Enabled
            || State(parent) != parentBefore || State(child) != childBefore
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Sort guard patch refresh, full state, RNG or live isolation differs.");
        _completedChecks.Add($"NativeCardSort:Types={profile.RegisteredTypeCount}:Pairs={pairs}:Rejected={rejected}:Cases={cases}:EqualNativeOrder:FullStateRng:ParentForkLive:SixteenSiblingForks:SevenPatchGates:UnknownVersionAndSource:CowMetadata:CloneMaterializeUpgrade:ChangedCachedId");
    }

    private static void SortNoOpPrefix() { }

    private static CardModel CreateUnknownSortCard()
    {
        // Avoid registering a test card in ModelDb or changing any generated card pool.
        AssemblyBuilder assembly = AssemblyBuilder.DefineDynamicAssembly(
            new AssemblyName("CombatSolver.Tests.UnknownSort"), AssemblyBuilderAccess.RunAndCollect);
        TypeBuilder type = assembly.DefineDynamicModule("Probe").DefineType("UnknownSortCard",
            TypeAttributes.Public | TypeAttributes.Sealed, typeof(CardModel));
        ConstructorBuilder constructor = type.DefineConstructor(MethodAttributes.Public,
            CallingConventions.Standard, Type.EmptyTypes);
        ILGenerator il = constructor.GetILGenerator();
        il.Emit(OpCodes.Ldstr, "This metadata probe cannot execute a game constructor.");
        il.Emit(OpCodes.Newobj, typeof(InvalidOperationException).GetConstructor([typeof(string)])!);
        il.Emit(OpCodes.Throw);
        return (CardModel)RuntimeHelpers.GetUninitializedObject(type.CreateType()!);
    }
