+using CombatSolver.Engine.Common;
+
+namespace CombatSolver;
+
+internal static class ProjectedShuffleSort
+{
+    // List.Sort(IComparer) adapts its comparer to a fresh delegate per call.
+    // The direct comparison overload can reuse this immutable delegate instead.
+    private static readonly Comparison<PredictedCard> NativeComparison =
+        static (left, right) => left.CompareNativeSortIdentity(right);
+
+    internal static bool TrySort(List<PredictedCard> cards, NativeCardSortProfile profile)
+    {
+        if (!profile.Enabled) return false;
+        foreach (PredictedCard card in cards)
+        {
+            // Reject the entire projection before changing its order; unknown types,
+            // changed IDs and native overrides retain the original comparison path.
+            if (card is null || !card.TryPrepareNativeSortIdentity(profile, out _)) return false;
+        }
+        // Immutable IDs may be shared by COW previews. Upgrade reads remain
+        // branch-owned, and the native getter is checked at root capture.
+        cards.Sort(NativeComparison);
+        return true;
+    }
+}
